# area: inheritance_mro
# hypothesis: super() inside a diamond resolves along the C3 MRO of the runtime class, so the checker must type the chained super().run() calls and LSP override checks consistently.
# spec: Python data model - super() follows the MRO of type(self); typing spec - overrides must be compatible with the base signature.
from typing import reveal_type


class A:
    def run(self) -> str:
        return 'A'


class B(A):
    def run(self) -> str:
        return 'B' + super().run()


class C(A):
    def run(self) -> str:
        return 'C' + super().run()


class D(B, C):
    def run(self) -> str:
        return 'D' + super().run()


class E(A):
    def run(self, extra: int) -> str:  # expect-error: incompatible override, extra is required
        return str(extra)


d = D()
reveal_type(d.run())
reveal_type(B().run())
print(d.run())
print(C().run())
print(A().run())

try:
    print(E().run(1))
except TypeError:
    print('rejected at runtime')
